      // help (app-tour.js): the logo and the ... menu, the beginner tour, the flowsheet legend
      tip_logo: "Aspen Workbench · Help",
      m_tour: "Beginner tour",
      m_legend: "Flowsheet legend",
      tip_legend: "What the colours, outlines and marks mean",
      tour_need_tab: "Open a tab first to take the tour",
      tour_step: "{0} / {1}",
      tour_prev: "Back",
      tour_next: "Next",
      tour_done: "Done",
      tour_skip: "Skip tour",
      tour1_t: "The Aspen model's flowsheet",
      tour1_b: "The flowsheet runs left to right, the way the streams flow. Scroll to zoom, drag empty space to pan, drag a block to move it; click the zoom percentage to see it all. ⋯ holds the layout, the legend and export. A pill at the edge such as “12 blocks >” means more lies that way; click it to go there.",
      tour2_t: "Click a block or stream for its inputs and results",
      tour2_b: "The inspector opens over the flowsheet, laid out like Aspen's form: the line under its name says whether the inputs are complete; the inputs come under Aspen's sheets, the first open, a sheet's name opens another; a greyed field is one the current settings do not use; the results are on the right. Click an input's box to change it; Enter or clicking elsewhere writes it to Aspen, Esc cancels. ⊕ (under the pointer) or a double-click adds a row to the program; its left edge drags it narrower.",
      tour3_t: "Run the simulation, see if it converged",
      tour3_b: "Run simulation (F5) works like Aspen's Run: one calculation with the current inputs. The model status beside it is a green dot while results are available; it reads Warnings, Errors, or Input changed when the results are out of date and need another run.",
      tour3_b_nosim: "This server cannot run the simulation on its own yet. Ask the AI to run it, or put a “run simulation” block in the program and press Run program (F5).",
      tour4_t: "The model file and saving",
      tour4_b: "This names the .bkp file Aspen has open. Click it for the full path and each block's Aspen messages. The disk button or Ctrl+S saves the model, backing up the old file first.",
      tour5_t: "Ask the AI",
      tour5_b: "Write a goal or a question here, such as “Why doesn't MEOHCOL converge?”. Select a block on the flowsheet first and the question is about it. The AI's replies and its edits to the block program show in the AI chat above.",
      tour5_b_ch: "Write a goal or a question here, such as “Why doesn't MEOHCOL converge?”. Select a block on the flowsheet first and the question is about it. The AI's replies and its edits to the block program show in the AI chat above; what it changes in the model (a value, a new block, a run) is listed in the Changes tab beside it, with the values before and after.",
      tour6_t: "Block programs: studies and optimization",
      tour6_b: "Only needed for a sensitivity study (sweep), a design spec, an optimization or heat integration. The easiest start: press ⊕ beside a field in the inspector and pick “Sweep this value…”. Run program (F6) runs only these blocks, unlike Run simulation (F5).",
      tour7_t: "See this again any time",
      tour7_b: "This tour, the flowsheet legend and the keyboard shortcuts are under Help in the ⋯ menu; the legend is also in the flowsheet's ⋯.",
      tour_rv_t: "Review mode",
      tour_rv_b: "Before the AI deletes, reinitializes, closes a model or overwrites a file, an approval request appears in Changes. Click to change the mode or pause the AI.",
      lg_fam: "The bar at a block's left: its family",
