      tour_done: "完成",
      tour_skip: "略過導覽",
      tour1_t: "Aspen 模型的流程圖",
      tour1_b: "流程圖依物流方向由左往右繪製。滾輪縮放、拖曳空白處平移、拖曳單元可移動，點縮放百分比顯示整張；⋯ 內有排列、圖例與匯出。邊緣的「12 個單元 >」表示該方向還有內容，點此即可前往。",
      tour2_t: "點單元或物流，檢視輸入與結果",
      tour2_b: "檢查器開在流程圖上，排得像 Aspen 的表單：名稱下的一行說明輸入是否齊全；輸入依 Aspen 的頁籤分組，第一頁展開，點頁籤名稱展開其他頁；灰色欄位是目前設定用不到的；結果在右側。點輸入框即可修改，按 Enter 或點別處寫入 Aspen，Esc 取消。列上出現的 ⊕ 或雙擊可將一列加入程式；拖曳左緣可調窄。欄位後的英文為 Aspen 表單上的名稱。",
      tour3_t: "執行模擬，檢視是否收斂",
      tour3_b: "「執行模擬」（F5）如同 Aspen 的 Run，以目前的輸入計算一次。旁邊的模型狀態在結果可用時只顯示綠點；有警告、有錯誤，或「輸入已變更」（結果過時，需重新執行）時顯示文字。",
      tour3_b_nosim: "此版伺服器尚無法單獨執行模擬。請 AI 執行，或在積木程式放「執行模擬（Run）」再按「執行程式」（F5）。",
      tour4_t: "模型檔與存檔",
      tour4_b: "此處為 Aspen 開啟的 .bkp 檔。點開可看完整路徑，以及每個單元的 Aspen 訊息。磁碟按鈕或 Ctrl+S 儲存模型，覆寫前自動備份舊檔。",
      tour5_t: "問 AI",
      tour5_b: "在此輸入目標或問題，例如「為什麼 MEOHCOL 不收斂？」。先在流程圖選取單元，問題即針對它。AI 的回覆與其對積木程式的修改顯示在上方的「AI 對話」。",
      tour5_b_ch: "在此輸入目標或問題，例如「為什麼 MEOHCOL 不收斂？」。先在流程圖選取單元，問題即針對它。AI 的回覆與其對積木程式的修改顯示在上方的「AI 對話」；對模型的修改（數值、新增單元、執行）列在旁邊的「變更」分頁，附修改前後的值。",
      tour6_t: "積木程式：參數研究與優化",
      tour6_b: "僅在做 Sensitivity（掃描）、Design Spec（調整到目標）、優化或熱整合時需要。最簡單的開始：在檢查器欄位旁按 ⊕，選「掃描這個值…」。「執行程式」（F6）只執行這裡的積木，與「執行模擬」（F5）不同。",
      tour7_t: "隨時可再看一次",
